<body>
  <header>
    <div class="logo">
      <div style="width:48px;height:48px;border-radius:10px;background:linear-gradient(135deg,var(--accent),#4ecfc6);display:grid;place-items:center;font-weight:700;color:#032423">PS</div>
      <div>
        <div style="font-weight:700">{{BUSINESS_NAME}}</div>
        <div style="font-size:13px;color:var(--muted)">Private sound designs for personal work</div>
      </div>
    </div>
    <nav>
      <a href="index.html">Home</a>
      <a href="events.html">Gatherings</a>
      <a href="private-sessions.html">Sessions</a>
      <a href="pricing.html">Plans</a>
      <a href="contact.html">Connect</a>
    </nav>
  </header>

  <main>
    <section class="card hero">
      <div>
        <h1 style="margin:0">Private sound sessions crafted to your needs</h1>
        <p style="margin:8px 0 0;color:var(--muted)">One-on-one sessions for focused rest, integration, or systematic recalibration. Choose how you wish to be supported.</p>
        <div style="margin-top:12px">
          <a class="cta" href="{{PRIMARY_CTA_URL}}">Book your private</a>
        </div>
      </div>
      <div style="text-align:right">
        <div style="font-size:13px;color:var(--muted)">Memberships offer priority booking</div>
        <div style="margin-top:8px"><a href="pricing.html" style="color:var(--accent);text-decoration:none">See membership plans</a></div>
      </div>
    </section>

    <div class="grid">
      <section>
        <div class="card">
          <strong>Customize session intensity</strong>
          <div style="font-size:13px;color:var(--muted);margin-top:6px">Use the mixer to tailor the recommended session format and tools.</div>
          <div style="margin-top:12px;display:flex;justify-content:flex-start;align-items:center;gap:8px" id="prefMixer">
            <div class="mixer">
              <button data-level="gentle" class="active">Lighter</button>
              <button data-level="medium">Balanced</button>
              <button data-level="intense">Deep</button>
            </div>
          </div>

          <div id="sessionRecs" style="margin-top:14px">
            <!-- injected -->
          </div>

          <div style="margin-top:16px">
            <strong>Book a private session</strong>
            <form class="session-form" onsubmit="return false;">
              <label>Preferred date</label>
              <input type="date" />
              <label>Length</label>
              <select>
                <option>45 minutes — Concise</option>
                <option>75 minutes — Full</option>
                <option>120 minutes — Deep</option>
              </select>
              <label>Notes (goals, sensitivities)</label>
              <textarea rows="3"></textarea>
              <div style="display:flex;gap:8px;margin-top:8px">
                <a class="cta" href="{{PRIMARY_CTA_URL}}">Request private</a>
                <a style="color:var(--muted);text-decoration:none" href="contact.html">Talk to us</a>
              </div>
            </form>
          </div>

          <div class="testimonial" id="psTestimonial">"A private hour that actually matched what I needed — deep and safe." — R.</div>
        </div>

        <div class="card" style="margin-top:12px">
          <strong>Contraindications & safety</strong>
          <div style="margin-top:8px;color:var(--muted);font-size:13px">If you have a history of seizures, severe cardiovascular conditions, or are pregnant, consult a physician before booking. Inform the facilitator about implanted devices and current medications. We can modify vibrations and volume for sensitivity.</div>
        </div>
      </section>

      <aside>
        <div class="card">
          <strong style="display:block">Session formats</strong>
          <div style="margin-top:10px;color:var(--muted);font-size:13px">We offer several private formulas; the mixer highlights one.</div>
          <div style="margin-top:12px" id="formats">
            <!-- formats injected -->
          </div>
          <div class="badges">
            <div class="badge" data-tip="Certified sound therapy practitioners">CT</div>
            <div class="badge" data-tip="Sanitized, private suite">PS</div>
          </div>
        </div>

        <div class="card" style="margin-top:12px">
          <strong>Contact</strong>
          <div style="margin-top:8px;color:var(--muted);font-size:13px">Call <strong>{{PHONE}}</strong> or email <a href="mailto:{{EMAIL}}" style="color:var(--accent)">{{EMAIL}}</a></div>
        </div>
      </aside>
    </div>
  </main>

  <footer>
    <div style="max-width:1100px;margin:18px auto;color:var(--muted);font-size:13px">© <span id="y"></span> {{BUSINESS_NAME}} — Private sessions in {{CITY}}, {{STATE}}</div>
  </footer>

  <script>
    (function(){
      const mixerBtns = document.querySelectorAll('#prefMixer .mixer button');
      const sessionRecs = document.getElementById('sessionRecs');
      const formatsEl = document.getElementById('formats');
      const testimonial = document.getElementById('psTestimonial');
      let mode = 'gentle';

      const formats = {
        gentle: [
          {title:'Soothing Align — 45min',desc:'Low-tone bowls, breath guidance, restorative silence.'},
          {title:'Rest Primer — 75min',desc:'Warm bowls, subtle layers, time for integration.'}
        ],
        medium:[
          {title:'Balanced Support — 75min',desc:'Rhythmic bowls with harmonic anchoring.'},
          {title:'Evening Recenter — 90min',desc:'Moderate immersion, grounding closure.'}
        ],
        intense:[
          {title:'Deep Field — 120min',desc:'Prolonged low frequencies, tailored intense focus.'},
          {title:'Resonant Reset — 120min',desc:'Extended protocol for deep recalibration.'}
        ]
      };

      function renderSessions(){
        sessionRecs.innerHTML = '';
        const list = formats[mode];
        list.forEach(f=>{
          const d = document.createElement('div');
          d.style.padding='10px';d.style.borderRadius='10px';d.style.background='linear-gradient(180deg,rgba(255,255,255,0.01),transparent)';d.style.marginBottom='8px';
          d.innerHTML = '<div style="font-weight:700">'+f.title+'</div><div style="font-size:13px;color:var(--muted)">'+f.desc+'</div>';
          sessionRecs.appendChild(d);
        });
      }

      function renderFormats(){
        formatsEl.innerHTML='';
        const all = Object.keys(formats);
        all.forEach(k=>{
          const el = document.createElement('div');el.style.padding='8px';el.style.borderRadius='8px';el.style.marginBottom='8px';el.style.background=k===mode? 'linear-gradient(90deg,var(--accent),#4ecfc6)': 'transparent';
          el.innerHTML = '<div style="font-weight:700">'+k.charAt(0).toUpperCase()+k.slice(1)+' formulas</div><div style="font-size:13px;color:var(--muted)">'+formats[k][0].title+'</div>';
          formatsEl.appendChild(el);
        });
      }

      mixerBtns.forEach(b=>{
        b.addEventListener('click',()=>{
