<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Plans & Membership — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#061217;--card:#08161b;--muted:#9fb7b5;--accent:#7fe0d8;--focus:#12b6ad;font-family:Inter,system-ui, -apple-system}
    body{margin:0;background:linear-gradient(180deg,#041018 0%,#06161a 100%);color:#eaf8f6;padding:36px}
    header{max-width:1100px;margin:0 auto;display:flex;justify-content:space-between;align-items:center}
    nav a{color:var(--muted);text-decoration:none;padding:8px 10px;border-radius:8px}
    nav a[href$="pricing.html"]{color:var(--accent);font-weight:700}
    main{max-width:1100px;margin:20px auto;display:grid;gap:18px}
    .hero{padding:18px;border-radius:14px;background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent)}
    .plans{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}
    .plan{background:var(--card);padding:16px;border-radius:12px}
    .price{font-weight:800;font-size:22px;color:var(--accent)}
    .cta{display:inline-block;padding:10px 14px;border-radius:10px;background:var(--accent);color:#042022;text-decoration:none;font-weight:700}
    .micro{margin-top:8px;color:var(--muted);font-size:13px}
    .toggle{display:flex;gap:8px;background:rgba(255,255,255,0.02);padding:6px;border-radius:999px}
    .toggle button{background:transparent;border:none;color:var(--muted);padding:8px 12px;border-radius:999px;cursor:pointer}
    .toggle button.active{background:var(--focus);color:#022}    
    .disclaimer{margin-top:12px;font-size:13px;color:var(--muted)}
    .proof{margin-top:12px;padding:12px;border-radius:10px;background:linear-gradient(180deg,rgba(255,255,255,0.01),transparent)}
    footer{max-width:1100px;margin:18px auto;color:var(--muted);font-size:13px}
    body::before{content:'';position:fixed;inset:0;opacity:0.06;background:url('assets/img/pattern.svg') repeat;mix-blend-mode:overlay;pointer-events:none}
    @media(max-width:880px){.plans{grid-template-columns:1fr}}
  </style>
</head>
<body>
  <header>
    <div style="display:flex;gap:12px;align-items:center">
      <div style="width:48px;height:48px;border-radius:10px;background:linear-gradient(135deg,var(--accent),#3fd5cc);display:grid;place-items:center;font-weight:700;color:#032423">PM</div>
      <div>
        <div style="font-weight:700">{{BUSINESS_NAME}}</div>
        <div style="font-size:13px;color:var(--muted)">Membership & single-session options</div>
      </div>
    </div>
    <nav>
      <a href="index.html">Home</a>
      <a href="events.html">Gatherings</a>
      <a href="private-sessions.html">Sessions</a>
      <a href="pricing.html">Plans</a>
      <a href="contact.html">Connect</a>
    </nav>
  </header>

  <main>
    <section class="hero">
      <h1 style="margin:0">Memberships that prioritize steady access</h1>
      <p style="margin:8px 0 0;color:var(--muted)">Choose the cadence that fits your life: pay-as-you-go, committed membership, or deep-work packages.</p>
      <div style="margin-top:12px;display:flex;gap:8px;align-items:center">
        <div class="toggle" role="tablist" aria-label="Billing duration">
          <button class="active" data-billing="monthly">Monthly</button>
          <button data-billing="annual">Annual</button>
        </div>
        <a class="cta" href="{{PRIMARY_CTA_URL}}">Begin membership</a>
      </div>
    </section>

    <section class="plans">
      <div class="plan">
        <div style="font-weight:700">Pulse Access</div>
        <div class="price" data-monthly="29" data-annual="290">$29/mo</div>
        <div class="micro">One guaranteed reservation per month + 10% on private sessions.</div>
        <div style="margin-top:12px"><a class="cta" href="{{PRIMARY_CTA_URL}}">Join Pulse</a></div>
      </div>

      <div class="plan" style="border:2px solid rgba(130,230,220,0.08)">
        <div style="font-weight:700">Deep Harbor (recommended)</div>
        <div class="price" data-monthly="69" data-annual="690">$69/mo</div>
        <div class="micro">Two reservations per month, priority booking, one private session at reduced rate annually.</div>
        <div style="margin-top:12px"><a class="cta" href="{{PRIMARY_CTA_URL}}">Join Deep Harbor</a></div>
      </div>

      <div class="plan">
        <div style="font-weight:700">Once & Return</div>
        <div class="price" data-monthly="0" data-annual="0">Pay-as-you-go</div>
        <div class="micro">No commitment. Purchase gatherings or privates at standard rates.</div>
        <div style="margin-top:12px"><a class="cta" href="book.html">Book single sessions</a></div>
      </div>
    </section>

    <section style="margin-top:12px">
      <div class="card" style="padding:14px;border-radius:12px;background:linear-gradient(180deg,rgba(255,255,255,0.01),transparent)">
        <strong>How pricing adjusts</strong>
        <p style="margin:8px 0 0;color:var(--muted)">Switching between monthly and annual toggles the visible price. Annual subscriptions reduce the effective monthly rate and include a welcome private short session on qualifying plans.</p>
        <div class="disclaimer">Contraindications: Please consult a clinician if you have epilepsy, are pregnant, have cardiac devices, or other implantable electronics. We modify protocols whenever needed — reach out before booking.</div>
      </div>

      <div class="proof" style="margin-top:12px">
        <strong>Member stories</strong>
        <div style="margin-top:8px;color:var(--muted)">"Membership keeps me committed — reliable places to reset." — J.</div>
      </div>
    </section>
  </main>

  <footer>
    <div style="max-width:1100px;margin:18px auto;color:var(--muted);font-size:13px">Questions about plans? Email <a href="mailto:{{EMAIL}}" style="color:var(--accent)">{{EMAIL}}</a> or call <strong>{{PHONE}}</strong></div>
  </footer>

  <script>
    (function(){
      const toggleBtns = document.querySelectorAll('.toggle button');
      const priceEls = document.querySelectorAll('.price');
      function setBilling(billing){
        toggleBtns.forEach(b=>b.classList.toggle('active', b.getAttribute('data-billing')===billing));
        priceEls.forEach(p=>{
          const m = p.getAttribute('data-monthly');
          const a = p.getAttribute('data-annual');
          if(billing==='monthly'){
            p.textContent = '$'+m+'/mo';
          } else {
            if(a && a!=='0'){
              p.textContent = '$'+a+'/yr';
            } else {
              p.textContent = 'Pay-as-you-go';
            }
          }
        });
      }
      toggleBtns.forEach(b=>b.addEventListener('click',()=>setBilling(b.getAttribute('data-billing'))));
      // initial
      setBilling('monthly');
    })();
  </script>
</body>
</html>"} 
